import{_ as e,o as r,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const h=JSON.parse('{"title":"Recette","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/recette.md","filePath":"src/guide/recette.md"}'),s={name:"guide/recette.md"};function d(i,t,o,l,u,c){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="recette" tabindex="-1">Recette <a class="header-anchor" href="#recette" aria-label="Permalink to &quot;Recette&quot;">​</a></h1><p>Cette page sert à vérifier ERA <strong>à la main</strong>, rôle par rôle, après chaque mise à jour (Alpha ou SaaS), avant de l&#39;annoncer aux utilisateurs. Elle ne remplace pas les tests automatiques : ceux-ci vérifient déjà, à chaque modification, que chaque rôle n&#39;ouvre que ses pages et que les parcours d&#39;argent et de notes donnent les bons montants et les bonnes moyennes.</p><p>La recette se concentre sur ce qu&#39;une machine ne voit pas : un PDF lisible et bien mis en page, un e-mail ou un SMS réellement reçu, un fichier qui s&#39;envoie depuis un téléphone, un paiement réel, une impression.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><ul><li>Prévoyez <strong>un compte de test par rôle</strong>, sur l&#39;établissement concerné, avec une adresse e-mail que vous pouvez lire.</li><li>Faites au moins une partie de la recette <strong>sur un téléphone</strong>, en particulier les rôles parent, élève, enseignant et vie scolaire.</li><li>Créez des données à votre nom (« Test recette ») et supprimez-les ou annulez-les à la fin, pour ne pas fausser les chiffres de l&#39;établissement.</li><li>Ne testez jamais un paiement en ligne réel avec une somme importante : le plus petit montant accepté suffit.</li></ul><div class="info custom-block"><p class="custom-block-title">Signaler un problème</p><p>Pour chaque point qui ne donne pas le résultat attendu, notez son <strong>numéro</strong> (par exemple PAR-4), le compte utilisé, ce que vous avez vu et une capture d&#39;écran. Un point non testé se note « non fait », pas « OK ».</p></div><h2 id="tous-les-roles" tabindex="-1">Tous les rôles <a class="header-anchor" href="#tous-les-roles" aria-label="Permalink to &quot;Tous les rôles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>TR-1</td><td>Se connecter avec chaque compte de test.</td><td>Le tableau de bord du rôle s&#39;ouvre, le menu ne montre que ses rubriques.</td></tr><tr><td>TR-2</td><td>Si la double authentification est active, se connecter sur un nouveau navigateur.</td><td>Un code à 6 chiffres arrive par e-mail en moins d&#39;une minute et ouvre la session.</td></tr><tr><td>TR-3</td><td>Cocher « Se souvenir de cet appareil », se déconnecter, se reconnecter.</td><td>Aucun code n&#39;est redemandé sur ce navigateur.</td></tr><tr><td>TR-4</td><td>Utiliser « Mot de passe oublié ».</td><td>L&#39;e-mail arrive, le lien fonctionne une seule fois.</td></tr><tr><td>TR-5</td><td>Ouvrir la cloche des notifications.</td><td>Les notifications récentes s&#39;affichent, les liens mènent à la bonne page.</td></tr><tr><td>TR-6</td><td>Basculer la langue en anglais, puis revenir en français.</td><td>Aucun texte ne reste dans l&#39;autre langue ni n&#39;affiche un code brut.</td></tr><tr><td>TR-7</td><td>Ouvrir l&#39;aide d&#39;une page, puis lancer une visite guidée.</td><td>L&#39;aide correspond à la page, la visite va jusqu&#39;au bout.</td></tr><tr><td>TR-8</td><td>Membre du personnel : déposer une demande depuis <strong>Mes demandes de congé</strong>.</td><td>La demande apparaît <strong>En attente</strong> et dans <strong>À approuver</strong> de la direction.</td></tr></tbody></table><h2 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>ADM-1</td><td><strong>Nouvel utilisateur</strong> avec votre adresse, puis <strong>Créer l&#39;utilisateur</strong>.</td><td>L&#39;invitation arrive par e-mail ; le lien permet de choisir un mot de passe.</td></tr><tr><td>ADM-2</td><td><strong>Renvoyer l&#39;invitation</strong> à un compte pas encore activé.</td><td>Un nouvel e-mail arrive, son lien permet d&#39;activer le compte.</td></tr><tr><td>ADM-3</td><td><strong>Modifier le logo</strong> dans les paramètres.</td><td>Le nouveau logo apparaît dans le menu et sur la page d&#39;accueil publique.</td></tr><tr><td>ADM-4</td><td><strong>Publier / republier les bulletins</strong> d&#39;une classe.</td><td>Les parents reçoivent une seule notification ; le bulletin s&#39;ouvre chez eux.</td></tr><tr><td>ADM-5</td><td>Ouvrir un bulletin PDF.</td><td>En-tête, notes, moyennes, rangs et appréciations sont lisibles, sans texte coupé ; l&#39;impression tient sur la page.</td></tr><tr><td>ADM-6</td><td><strong>Sauvegarder maintenant</strong>, puis télécharger l&#39;archive.</td><td>L&#39;archive se télécharge et s&#39;ouvre.</td></tr><tr><td>ADM-7</td><td>Exporter les notes d&#39;une classe en Excel, puis réimporter le fichier.</td><td>Le fichier s&#39;ouvre dans Excel ; l&#39;import ne crée ni doublon ni erreur.</td></tr><tr><td>ADM-8</td><td>Ouvrir la page d&#39;accueil publique de l&#39;établissement sur un téléphone.</td><td>Textes, images et contacts s&#39;affichent correctement, sans débordement.</td></tr></tbody></table><h2 id="enseignant" tabindex="-1">Enseignant <a class="header-anchor" href="#enseignant" aria-label="Permalink to &quot;Enseignant&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>ENS-1</td><td>Sur un téléphone, <strong>Faire l&#39;appel</strong> d&#39;une classe puis <strong>Enregistrer l&#39;appel</strong>.</td><td>La liste est utilisable au doigt ; l&#39;appel apparaît pour la vie scolaire.</td></tr><tr><td>ENS-2</td><td><strong>Nouvelle évaluation</strong>, puis saisir les <strong>Notes</strong> de quelques élèves.</td><td>Le barème est prérempli à 20 ; les notes à virgule sont acceptées.</td></tr><tr><td>ENS-3</td><td>Depuis <strong>Ma classe</strong>, saisir des appréciations.</td><td>Elles apparaissent sur le bulletin PDF, sans être coupées.</td></tr><tr><td>ENS-4</td><td><strong>Cahier de texte</strong> → <strong>Nouvelle entrée</strong> avec une pièce jointe.</td><td>L&#39;entrée apparaît dans le <strong>Cahier de texte</strong> de l&#39;élève ; la pièce jointe s&#39;ouvre.</td></tr><tr><td>ENS-5</td><td>Consulter son emploi du temps.</td><td>Les créneaux correspondent à ceux saisis par l&#39;administration.</td></tr></tbody></table><h2 id="vie-scolaire" tabindex="-1">Vie scolaire <a class="header-anchor" href="#vie-scolaire" aria-label="Permalink to &quot;Vie scolaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>VS-1</td><td>Ouvrir les <strong>Justifications d&#39;absence</strong>, consulter une pièce justificative.</td><td>La pièce (photo ou PDF) s&#39;ouvre et se lit.</td></tr><tr><td>VS-2</td><td><strong>Approuver</strong> une justification, <strong>Rejeter</strong> une autre.</td><td>Le parent est prévenu de chaque décision.</td></tr><tr><td>VS-3</td><td><strong>Nouvel incident</strong>, puis <strong>Convoquer un conseil</strong>.</td><td>Le conseil apparaît avec sa date et ses membres.</td></tr><tr><td>VS-4</td><td><strong>Enregistrer la décision</strong>, puis <strong>Télécharger le procès-verbal</strong>.</td><td>Le PDF reprend la décision et les présents, lisible et bien mis en page.</td></tr><tr><td>VS-5</td><td>Sur un téléphone, <strong>Pointage cantine</strong> avec <strong>Tous ont mangé</strong>.</td><td>Le pointage s&#39;enregistre en un geste.</td></tr><tr><td>VS-6</td><td>Sur un téléphone, <strong>Pointage transport</strong> en <strong>Montée</strong> puis <strong>Descente</strong>.</td><td>Les deux pointages s&#39;enregistrent.</td></tr></tbody></table><h2 id="secretariat" tabindex="-1">Secrétariat <a class="header-anchor" href="#secretariat" aria-label="Permalink to &quot;Secrétariat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>SEC-1</td><td>Déposer une candidature depuis la page publique, avec des pièces.</td><td>Elle arrive dans <strong>Dossiers à traiter</strong>, les pièces s&#39;ouvrent.</td></tr><tr><td>SEC-2</td><td><strong>Examiner</strong> puis <strong>Valider</strong> le dossier et <strong>Affecter à une classe</strong>.</td><td>La famille est prévenue par e-mail ; l&#39;élève apparaît dans la classe.</td></tr><tr><td>SEC-3</td><td><strong>Refuser</strong> un autre dossier avec un motif.</td><td>La famille reçoit le refus avec le motif.</td></tr><tr><td>SEC-4</td><td>Examiner la demande de transfert de site de PAR-3, puis l&#39;approuver.</td><td>Une fois le transfert validé, l&#39;élève apparaît sur le site de destination.</td></tr><tr><td>SEC-5</td><td>Changer un élève de classe.</td><td>Ses frais suivent, ses notes passées restent visibles.</td></tr></tbody></table><h2 id="caisse" tabindex="-1">Caisse <a class="header-anchor" href="#caisse" aria-label="Permalink to &quot;Caisse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>CAI-1</td><td>Encaisser un paiement en espèces, puis <strong>Télécharger le reçu</strong>.</td><td>Le reçu PDF porte le bon élève et le bon montant, et s&#39;imprime correctement.</td></tr><tr><td>CAI-2</td><td>Encaisser un paiement par virement avec une référence.</td><td>La référence figure sur le reçu.</td></tr><tr><td>CAI-3</td><td>Saisir une dépense avec un justificatif.</td><td>Le justificatif s&#39;ouvre ; la dépense part en validation.</td></tr><tr><td>CAI-4</td><td>Lancer l&#39;export comptable d&#39;un mois.</td><td>Le fichier s&#39;ouvre dans le tableur et les totaux correspondent à l&#39;écran.</td></tr><tr><td>CAI-5</td><td>Si le paiement en ligne est actif, vérifier le paiement fait en PAR-5.</td><td>Il apparaît comme réglé, avec la bonne référence.</td></tr></tbody></table><h2 id="parent" tabindex="-1">Parent <a class="header-anchor" href="#parent" aria-label="Permalink to &quot;Parent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>PAR-1</td><td>Sur un téléphone, ouvrir le bulletin publié en ADM-4.</td><td>Le PDF s&#39;ouvre et se lit sur le téléphone.</td></tr><tr><td>PAR-2</td><td><strong>Justifier</strong> une absence avec une <strong>Pièce justificative</strong> prise en photo.</td><td>La photo s&#39;envoie depuis le téléphone ; la vie scolaire la voit.</td></tr><tr><td>PAR-3</td><td><strong>Demander un transfert</strong> de site pour son enfant.</td><td>La demande arrive au secrétariat (voir SEC-4).</td></tr><tr><td>PAR-4</td><td>Choisir des services optionnels, puis <strong>Enregistrer mes choix</strong>.</td><td>Les frais correspondants apparaissent dans le solde.</td></tr><tr><td>PAR-5</td><td><strong>Payer en ligne</strong> le plus petit montant possible, puis <strong>Envoyer la demande de paiement</strong>.</td><td>La demande arrive sur le téléphone, le paiement aboutit après validation, le solde baisse.</td></tr><tr><td>PAR-6</td><td>Répéter PAR-5 en refusant la validation sur le téléphone.</td><td>Le paiement n&#39;est pas compté ; le solde ne change pas.</td></tr><tr><td>PAR-7</td><td><strong>Télécharger le reçu</strong> d&#39;un paiement.</td><td>Le reçu PDF est le même que celui de la caisse.</td></tr></tbody></table><h2 id="eleve" tabindex="-1">Élève <a class="header-anchor" href="#eleve" aria-label="Permalink to &quot;Élève&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>ELV-1</td><td>Sur un téléphone, ouvrir <strong>Mon portail</strong>.</td><td>Les sections Notes, Bulletins, Documents et Cahier de texte s&#39;affichent.</td></tr><tr><td>ELV-2</td><td>Ouvrir le bulletin, puis la pièce jointe de ENS-4.</td><td>Les deux fichiers s&#39;ouvrent.</td></tr><tr><td>ELV-3</td><td>Vérifier une note saisie en ENS-2.</td><td>La note et l&#39;évaluation sont celles saisies par l&#39;enseignant.</td></tr></tbody></table><h2 id="internat" tabindex="-1">Internat <a class="header-anchor" href="#internat" aria-label="Permalink to &quot;Internat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>INT-1</td><td><strong>Nouveau lit</strong>, puis y affecter un élève.</td><td>Le lit apparaît occupé.</td></tr><tr><td>INT-2</td><td>Sur un téléphone, <strong>Présences internat</strong> Soir puis Matin.</td><td>Les deux appels s&#39;enregistrent ; un absent est signalé.</td></tr></tbody></table><h2 id="infirmerie" tabindex="-1">Infirmerie <a class="header-anchor" href="#infirmerie" aria-label="Permalink to &quot;Infirmerie&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>INF-1</td><td><strong>Nouveau passage</strong> avec l&#39;issue <strong>Retour en classe</strong>.</td><td>Le passage apparaît dans la liste ; aucun parent n&#39;est prévenu.</td></tr><tr><td>INF-2</td><td><strong>Nouveau passage</strong> avec l&#39;issue <strong>Renvoyé à la maison</strong>.</td><td>Les parents reçoivent une notification avec le motif et l&#39;heure.</td></tr></tbody></table><h2 id="gestion-documentaire" tabindex="-1">Gestion documentaire <a class="header-anchor" href="#gestion-documentaire" aria-label="Permalink to &quot;Gestion documentaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>GED-1</td><td>Dans le dossier d&#39;un élève, <strong>Déposer</strong> un PDF.</td><td>Le document apparaît sous le bon type et s&#39;ouvre.</td></tr><tr><td>GED-2</td><td>Sur un téléphone, <strong>Prendre une photo</strong> de deux pages imprimées.</td><td>Les pages sont réunies en un seul PDF lisible, dans l&#39;ordre.</td></tr><tr><td>GED-3</td><td><strong>Rechercher dans les documents</strong> un mot des pages de GED-2.</td><td>Le document est retrouvé.</td></tr><tr><td>GED-4</td><td><strong>Reprise d&#39;archives</strong> de quelques fichiers, puis <strong>Classer</strong> chacun.</td><td>Chaque numérisation se range dans le bon dossier, aucune n&#39;est en double.</td></tr><tr><td>GED-5</td><td>Produire un certificat de scolarité depuis un <strong>modèle</strong>.</td><td>Le PDF porte le bon nom et la bonne classe, sur l&#39;en-tête de l&#39;établissement, et se range dans le dossier de l&#39;élève.</td></tr></tbody></table><h2 id="direction-de-site-et-direction-generale" tabindex="-1">Direction de site et direction générale <a class="header-anchor" href="#direction-de-site-et-direction-generale" aria-label="Permalink to &quot;Direction de site et direction générale&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>À faire</th><th>Attendu</th></tr></thead><tbody><tr><td>DIR-1</td><td>Ouvrir <strong>À approuver</strong>.</td><td>La demande de congé de TR-8 et la dépense de CAI-3 (si elle est sous le seuil) y figurent.</td></tr><tr><td>DIR-2</td><td><strong>Accorder</strong> le congé, <strong>Refuser</strong> la dépense avec un motif.</td><td>Chaque demandeur reçoit la notification, avec le motif en cas de refus.</td></tr><tr><td>DIR-3</td><td>Ouvrir le pilotage.</td><td>Les chiffres reprennent les paiements, absences et notes de la recette.</td></tr><tr><td>DG-1</td><td>Direction générale : ouvrir <strong>À approuver</strong>.</td><td>Elle voit aussi les dépenses au-delà du seuil et les demandes de tous les sites.</td></tr><tr><td>DG-2</td><td>Faire saisir par la caisse une dépense au-delà du seuil, puis ouvrir <strong>À approuver</strong> en direction de site.</td><td>La dépense n&#39;y figure pas ; elle n&#39;apparaît que chez la direction générale.</td></tr></tbody></table><h2 id="a-la-fin" tabindex="-1">À la fin <a class="header-anchor" href="#a-la-fin" aria-label="Permalink to &quot;À la fin&quot;">​</a></h2><ul><li>Annulez ou supprimez les données « Test recette » créées pendant la recette, y compris le remboursement du paiement en ligne de PAR-5 si besoin.</li><li>Transmettez la liste des points en échec, avec leur numéro, avant d&#39;annoncer la mise à jour.</li></ul>',32)])])}const g=e(s,[["render",d]]);export{h as __pageData,g as default};
